user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "CONFIRMS_REQUIREMENT_FROM_OBSERVED_OUTPUT",
    "definition": "The reasoning interprets concrete content of an observation as satisfying a specific previously stated requirement, by mapping observed values or artifacts onto the attributes that requirement demands.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that maps observed output content onto required attributes and declares the requirement met."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result supplying the concrete values or artifacts cited as evidence of requirement fulfillment."
      }
    ],
    "assertion_conditions": [
      "The reasoning names at least one required attribute (field, behavior, file, setting) and cites corresponding observable content from the observation.",
      "The reasoning states or implies that the cited content demonstrates the requirement is satisfied, rather than merely describing the output."
    ],
    "exclusion_conditions": [
      "The reasoning restates or transcribes the observation without linking it to a requirement.",
      "The observation contains no identifiable content corresponding to the requirement being claimed.",
      "The reasoning claims satisfaction without any observed evidence."
    ]
  },
  {
    "name": "EXPLAINS_ANOMALOUS_RESULT_WITH_CAUSAL_HYPOTHESIS",
    "definition": "Faced with an observation that contradicts the expected outcome, the reasoning proposes a causal or mechanistic account of why the deviation occurred, instead of accepting the result at face value.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text constructing the explanation for the unexpected result."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result whose content deviates from what the agent expected."
      }
    ],
    "assertion_conditions": [
      "The observation's outcome differs from the outcome the agent anticipated (for example, no rejections where rejections were expected).",
      "The reasoning identifies a mechanism (timing, pacing, queueing, serialization, absent capability) that would produce that deviation.",
      "The explanation is presented as the reason the observed result occurred, not as an unrelated general remark."
    ],
    "exclusion_conditions": [
      "The observation matches the expectation, so no deviation needs explaining.",
      "The reasoning only repeats the result or expresses surprise without proposing any mechanism.",
      "The reasoning attributes the result to a mechanism that is incompatible with the observed content."
    ]
  },
  {
    "name": "ADAPTS_PROBE_TO_ELIMINATE_IDENTIFIED_CONFOUND",
    "definition": "The reasoning diagnoses a confound or limitation in a previous measurement technique, and the following action changes how the measurement is performed specifically to remove that confound.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text identifying the confound (for example, per-invocation startup delay spacing requests, or an unsupported option) and prescribing the adjusted technique."
      },
      {
        "name": "adapted_action",
        "type": "action",
        "description": "The tool invocation performing the measurement with the adjusted technique."
      }
    ],
    "assertion_conditions": [
      "The reasoning names a specific property of the earlier technique that distorted or invalidated the measurement.",
      "The adapted action differs from the earlier technique in exactly the respect the reasoning identified.",
      "The reasoning presents the adjustment as a way to obtain a valid measurement, not as an unrelated new objective."
    ],
    "exclusion_conditions": [
      "The action repeats the same technique without addressing the identified confound.",
      "The reasoning provides no identifiable flaw in the previous approach.",
      "The action changes technique for reasons unrelated to measurement validity (for example, convenience or unrelated requirements)."
    ]
  },
  {
    "name": "TESTS_BEHAVIORAL_GUARANTEE_WITH_STRESS_PROBE",
    "definition": "An action deliberately generates load or stress conditions to test whether a configured behavioral guarantee (throttling, limiting, rejection behavior) actually holds, and the resulting observation supplies interpretable evidence about that guarantee.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The tool invocation that drives demand beyond normal levels to exercise the claimed behavior."
      },
      {
        "name": "guarantee_reasoning",
        "type": "reasoning",
        "description": "The agent text stating the behavioral guarantee under test and the outcome pattern that would confirm or refute it."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The tool result reporting the distribution or pattern of responses produced by the probe."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a behavioral guarantee and an expected signature of it holding (for example, a fraction of rejections when demand exceeds the allowance).",
      "The probe action is constructed to exceed the conditions under which the guarantee would be inert.",
      "The probe result reports an outcome pattern that can be compared against the expected signature."
    ],
    "exclusion_conditions": [
      "The action exercises only normal single-request usage and cannot discriminate whether the guarantee holds.",
      "The result is not interpretable with respect to the stated guarantee (for example, the probe failed to execute).",
      "No expected signature is stated, so the result cannot confirm or refute anything."
    ]
  },
  {
    "name": "IMPLEMENTS_DIAGNOSED_CORRECTION_AS_CHANGE",
    "definition": "The agent modifies an artifact (configuration, file, setting) in exactly the way its own prior diagnostic reasoning concluded was necessary, so the change is the operational realization of a diagnosis rather than an arbitrary edit.",
    "parameters": [
      {
        "name": "change_action",
        "type": "action",
        "description": "The tool invocation that rewrites or alters the artifact."
      },
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The agent text concluding which specific modification is needed and why."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a deficiency or undesired default behavior and names the modification that would correct it.",
      "The change action applies that named modification to the artifact.",
      "The correspondence between the concluded modification and the applied change is identifiable in the node contents."
    ],
    "exclusion_conditions": [
      "The change action implements something other than what the reasoning concluded was required.",
      "The reasoning offers no specific corrective modification, only a general observation.",
      "The action is a read-only inspection rather than an alteration."
    ]
  },
  {
    "name": "SELECTS_VARIANT_BY_ANTICIPATED_EVALUATION",
    "definition": "The reasoning chooses among multiple defensible implementation variants by predicting how an external evaluator or downstream check would respond to each variant, rather than by inherent correctness alone.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text weighing alternatives and explaining the choice in terms of predicted evaluation outcomes."
      }
    ],
    "assertion_conditions": [
      "The reasoning presents at least two viable implementation variants or interpretations.",
      "The reasoning justifies the selection by predicting how an external check, test, or grader would treat each variant.",
      "The reasoning commits to one variant as a result of that prediction."
    ],
    "exclusion_conditions": [
      "The reasoning selects a variant purely on technical correctness with no reference to anticipated evaluation.",
      "Only one option is considered, so no selection among alternatives occurs.",
      "The reasoning defers the choice without committing."
    ]
  },
  {
    "name": "VALIDATES_BEFORE_ACTIVATION",
    "definition": "A single action gates an activation or restart of a service on a prior validity check, so that activation proceeds only if the check passes.",
    "parameters": [
      {
        "name": "gated_action",
        "type": "action",
        "description": "The tool invocation combining a validity check with a conditional activation or reload of the service."
      }
    ],
    "assertion_conditions": [
      "The invocation performs an explicit validity or syntax check of the configuration.",
      "The activation or reload operation is conditioned on that check succeeding within the same invocation.",
      "The check and the activation are distinguishable parts of the invocation."
    ],
    "exclusion_conditions": [
      "Activation or reload is performed without any preceding validity check.",
      "The invocation only performs a check and no activation.",
      "The check does not gate the activation (for example, they run unconditionally in sequence)."
    ]
  },
  {
    "name": "AUDITS_ALL_STATED_REQUIREMENTS_WITH_ENUMERATED_CHECKS",
    "definition": "The agent performs a consolidated audit that enumerates each stated requirement and pairs it with a direct check, with the observation reporting a per-requirement status that the subsequent reasoning aggregates into an overall completion judgment.",
    "parameters": [
      {
        "name": "audit_reasoning",
        "type": "reasoning",
        "description": "The agent text declaring an intention to verify every stated requirement as a complete set."
      },
      {
        "name": "audit_action",
        "type": "action",
        "description": "The tool invocation issuing one enumerated check per requirement."
      },
      {
        "name": "audit_result",
        "type": "observation",
        "description": "The tool result reporting the outcome of each individual check."
      }
    ],
    "assertion_conditions": [
      "The reasoning frames the check as covering the full set of stated requirements, not a subset.",
      "The audit action produces an individually identifiable result per requirement.",
      "The audit result reports per-requirement statuses that can be aggregated into an overall verdict."
    ],
    "exclusion_conditions": [
      "The check covers only one requirement or an arbitrary subset.",
      "The result aggregates outcomes in a way that no per-requirement status is identifiable.",
      "Requirements are asserted as met without a corresponding executed check."
    ]
  }
]

Existing registry:
[
  {
    "name": "PLANS_NEXT_ACTION",
    "definition": "The reasoning explicitly expresses an intended future action or sequence of actions that the agent has not yet performed.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that states an intended future action or sequence."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one intended future action or step.",
      "The intended action is presented as something still to be done rather than as already completed."
    ],
    "exclusion_conditions": [
      "The reasoning only reports or summarizes actions already completed.",
      "The reasoning states a conclusion, diagnosis, or observation summary without expressing future intent.",
      "The reasoning states only a general goal or desired result without identifying any intended action or step."
    ]
  },
  {
    "name": "IDENTIFIES_DEFECT_FROM_OBSERVATION",
    "definition": "The reasoning uses identifiable content of an observation to identify a defect, error, or incompleteness in the artifact or state described by that observation.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that identifies the defect, error, or gap."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation whose content provides evidence of the defective or incomplete state."
      }
    ],
    "assertion_conditions": [
      "The observation contains identifiable evidence of an incomplete, erroneous, or otherwise defective state.",
      "The reasoning explicitly characterizes that state as a problem, gap, or defect requiring attention or correction."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats or describes the observation without identifying a defect.",
      "The observation does not contain evidence of a defect or gap.",
      "The reasoning asserts a defect that is not supported by identifiable observation content."
    ]
  },
  {
    "name": "FORMULATES_CORRECTIVE_SOLUTION",
    "definition": "The reasoning derives and specifies a concrete method, content, or set of steps intended to remedy an identified defect or gap.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that derives and specifies the corrective method or steps."
      }
    ],
    "assertion_conditions": [
      "The reasoning refers to an identified defect, gap, or problematic state.",
      "The reasoning provides at least one concrete corrective step, replacement content, or method intended to address that defect."
    ],
    "exclusion_conditions": [
      "The reasoning only states that a fix is needed without specifying how to perform it.",
      "The reasoning only summarizes a correction that was already carried out.",
      "The reasoning only plans to investigate or gather information without formulating a corrective method."
    ]
  },
  {
    "name": "ACTION_IMPLEMENTS_PLANNED_STEP",
    "definition": "The action carries out a step that the reasoning explicitly specified as an intended future action or corrective step.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action performing the planned step."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node specifying the intended step, target, or corrective content."
      }
    ],
    "assertion_conditions": [
      "The reasoning specifies a future action, target, or corrective content.",
      "The action performs that specified step using a corresponding operation, target, or content."
    ],
    "exclusion_conditions": [
      "The action is unrelated to the reasoning's stated intent.",
      "The reasoning only describes an outcome or diagnosis without specifying an action.",
      "The action is an unplanned reaction that is not described in the reasoning."
    ]
  },
  {
    "name": "CHECKS_PREREQUISITE_AVAILABILITY",
    "definition": "The reasoning identifies a tool, resource, or environment capability on which a planned or contemplated action depends, a check action queries that prerequisite's availability, version, or readiness, and the observation reports its status.",
    "parameters": [
      {
        "name": "prerequisite_reasoning",
        "type": "reasoning",
        "description": "The reasoning node indicating that a planned or contemplated action depends on a required capability or resource, or that its availability must be verified."
      },
      {
        "name": "check_action",
        "type": "action",
        "description": "The action that queries availability, version, or readiness of the prerequisite."
      },
      {
        "name": "check_result",
        "type": "observation",
        "description": "The observation reporting the prerequisite's availability, version, or readiness."
      }
    ],
    "assertion_conditions": [
      "The reasoning links a planned or contemplated action to a prerequisite tool, resource, capability, or environment condition.",
      "The check action queries the availability, version, or readiness of that prerequisite rather than performing the planned work itself.",
      "The observation reports whether the prerequisite is available or ready."
    ],
    "exclusion_conditions": [
      "No planned or contemplated action depends on the checked prerequisite.",
      "The check action queries something unrelated to the stated dependency.",
      "The observation does not report availability, version, or readiness of the prerequisite."
    ]
  },
  {
    "name": "TESTS_ASSUMPTION_WITH_PROBE",
    "definition": "A targeted action tests a specific uncertainty or hypothesis identified in reasoning, and the resulting observation provides interpretable evidence bearing on that uncertainty.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The targeted action that probes the uncertainty or hypothesis."
      },
      {
        "name": "assumption_reasoning",
        "type": "reasoning",
        "description": "The reasoning node identifying the hypothesis, property, or uncertainty being tested."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The observation reporting a result relevant to the hypothesis or uncertainty."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific uncertainty, hypothesis, or property to be checked.",
      "The probe action is directed at obtaining evidence about that specific uncertainty.",
      "The observation reports a result that can be interpreted as evidence about the uncertainty."
    ],
    "exclusion_conditions": [
      "The action is unrelated to the stated uncertainty or hypothesis.",
      "The observation does not address the uncertainty being tested.",
      "No identifiable uncertainty or hypothesis motivates the action."
    ]
  },
  {
    "name": "DIAGNOSES_FAILURE_CAUSE",
    "definition": "The reasoning assigns a specific causal mechanism to a failure or error reported in an observation, explaining how the failure arose rather than merely restating the error text.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node explaining the cause or mechanism of the failure."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the error or unsuccessful outcome."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error, non-zero exit status, or otherwise unsuccessful outcome.",
      "The reasoning identifies a specific cause or mechanism responsible for that failure, going beyond the literal error message.",
      "The stated cause is consistent with the facts reported in the observation."
    ],
    "exclusion_conditions": [
      "The reasoning merely notes that a failure occurred.",
      "The reasoning proposes a retry without explaining the cause.",
      "The reasoning only repeats or paraphrases the error message without explaining it.",
      "The stated cause contradicts the observation's reported facts.",
      "The observation does not report a failure or error."
    ]
  },
  {
    "name": "CORRECTS_FAILED_ACTION_WITH_DIAGNOSIS",
    "definition": "A subsequent action alters the approach, parameters, or resource of an earlier failing action in a way that follows from a diagnosed cause, aiming to overcome the observed failure.",
    "parameters": [
      {
        "name": "corrected_action",
        "type": "action",
        "description": "The subsequent action that changes the approach, parameters, or resource."
      },
      {
        "name": "diagnostic_reasoning",
        "type": "reasoning",
        "description": "The reasoning node diagnosing the cause and identifying the needed change."
      },
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The observation reporting the earlier failure or error."
      }
    ],
    "assertion_conditions": [
      "The failure observation reports an unsuccessful action or error.",
      "The reasoning diagnoses the cause of the failure and identifies a needed change.",
      "The corrected action implements the relevant change in parameter, resource, or approach."
    ],
    "exclusion_conditions": [
      "The subsequent action repeats the failed action without a relevant change.",
      "The action is not based on the diagnosed cause.",
      "The observation does not report a failure or error."
    ]
  },
  {
    "name": "CONFIRMS_EXPECTED_OUTCOME_FROM_OBSERVATION",
    "definition": "The reasoning interprets an observation as confirming that an expected condition, success criterion, or intended outcome has been achieved.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node interpreting the observation as confirmation."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation providing evidence that matches the expected outcome."
      }
    ],
    "assertion_conditions": [
      "The reasoning states or implies an expected outcome or success criterion.",
      "The observation contains identifiable evidence matching that expectation.",
      "The reasoning explicitly treats the observation as confirmation that the expected outcome holds."
    ],
    "exclusion_conditions": [
      "The observation is used only as an input to further action rather than as confirmation.",
      "The reasoning merely predicts an outcome without checking it against an observation.",
      "The observation is ambiguous or unrelated to the expected condition."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning draws an explicit conclusion, diagnosis, or assessment that is supported by identifiable content of the observation.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node expressing the conclusion, diagnosis, or assessment."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation supplying evidence for that conclusion."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a conclusion, diagnosis, or assessment beyond merely restating the observation.",
      "The conclusion depends on specific identifiable content of the observation, such as presence or absence of items, status, version, or output."
    ],
    "exclusion_conditions": [
      "The reasoning repeats or describes the observation without inferring anything from it.",
      "The observation is unrelated to the conclusion or contains no information that supports it.",
      "The conclusion rests only on prior knowledge with no identifiable evidential link to the observation."
    ]
  },
  {
    "name": "IDENTIFIES_MISSING_PREREQUISITE",
    "definition": "The reasoning identifies a capability, component, account, resource, or configuration that the goal requires but that is absent or insufficient, using identifiable content of the observation as evidence of the gap.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node stating that something required for the goal is missing or inadequate."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation providing evidence of the absence or insufficiency."
      }
    ],
    "assertion_conditions": [
      "The reasoning states that something needed for the task is missing, unavailable, or inadequate.",
      "The observation contains identifiable evidence of the absence or insufficiency, such as a failed lookup, empty listing, missing binary, or missing package."
    ],
    "exclusion_conditions": [
      "The reasoning merely notes a fact without linking it to a requirement of the goal.",
      "No requirement or gap is stated.",
      "The observation does not show absence or insufficiency of the required item."
    ]
  },
  {
    "name": "CONFIGURES_EVENT_TRIGGERED_AUTOMATION",
    "definition": "The action creates or updates a configuration artifact that associates a specified event with a downstream operation, so that later occurrences of the event automatically cause that operation without further manual invocation.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action node that writes or installs the automation configuration."
      }
    ],
    "assertion_conditions": [
      "The action writes or installs a hook, trigger, listener, job, or equivalent automation configuration.",
      "The configuration content associates a specified event or condition with a downstream operation to be performed automatically."
    ],
    "exclusion_conditions": [
      "The action performs a one-off operation with no persistent trigger.",
      "The action only documents a procedure for later manual execution.",
      "The configured artifact does not connect an event or condition to an automatic response."
    ]
  },
  {
    "name": "MITIGATES_ANTICIPATED_FAILURE",
    "definition": "Reasoning identifies a foreseeable failure mode that could prevent the goal, an action applies a preventive measure addressing that failure mode before it occurs, and an observation provides evidence that the preventive measure is in place.",
    "parameters": [
      {
        "name": "risk_reasoning",
        "type": "reasoning",
        "description": "The reasoning node naming the anticipated failure mode or pitfall and its relevance to the goal."
      },
      {
        "name": "mitigation_action",
        "type": "action",
        "description": "The action node applying a preventive measure against that failure mode."
      },
      {
        "name": "state_observation",
        "type": "observation",
        "description": "The observation node showing evidence consistent with the preventive measure having been applied."
      }
    ],
    "assertion_conditions": [
      "The risk_reasoning names a specific failure mode or pitfall that could prevent the goal, rather than a vague risk.",
      "The mitigation_action changes configuration, permissions, or state in a way that prevents or reduces that failure mode before it occurs.",
      "The state_observation contains evidence consistent with the mitigation being applied."
    ],
    "exclusion_conditions": [
      "The reasoning only mentions a general risk without a corresponding preventive action.",
      "The action does not address the identified failure mode, or addresses it only after the failure occurred.",
      "The observation does not show the mitigated state."
    ]
  },
  {
    "name": "VALIDATES_CONFIGURATION_BEFORE_ACTIVATION",
    "definition": "A configuration artifact is checked for validity by a validation operation before the configured component is activated or relied upon, and the observed result confirms that the validation succeeded.",
    "parameters": [
      {
        "name": "validation_reasoning",
        "type": "reasoning",
        "description": "The reasoning node indicating that the configuration should be validated before activation."
      },
      {
        "name": "validation_action",
        "type": "action",
        "description": "The action node performing the configuration test or syntax check; activation of the component may occur in the same action or a subsequent one."
      },
      {
        "name": "validation_observation",
        "type": "observation",
        "description": "The observation node reporting the validation result."
      }
    ],
    "assertion_conditions": [
      "The validation_reasoning or the validation_action indicates a validation step is to be performed before the component is activated.",
      "The validation_action executes a configuration test, syntax check, or equivalent validity check on the artifact.",
      "The validation_observation reports a successful validation result, and activation follows that success."
    ],
    "exclusion_conditions": [
      "The component is activated without any preceding validation step.",
      "The validation fails or its result is not interpretable as success.",
      "Only a post-activation inspection is performed, with no pre-activation check."
    ]
  },
  {
    "name": "PREDICTS_RESIDUAL_ARTIFACT_INTERFERENCE",
    "definition": "The reasoning predicts that state left behind by the agent's own activity (testing, probing, or configuration) will cause a later required operation, typically performed by the end user or an external checker, to fail or behave incorrectly, and uses that prediction as the reason to remove or reset that residual state before handoff.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that identifies residual self-created state, predicts its adverse effect on a later operation, and motivates its removal."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies specific residual state produced by the agent's own activity, such as test commits, branches, keys, files, or running test artifacts.",
      "The reasoning predicts a concrete adverse consequence for a later operation, for example that a required commit will fail because nothing changed, that a push will report nothing to update, or that a check will observe pre-modified content.",
      "The reasoning treats that prediction as the justification for removing or resetting the identified state before handoff."
    ],
    "exclusion_conditions": [
      "The reasoning expresses only generic cleanliness or tidiness concerns without a predicted operational consequence.",
      "The predicted consequence concerns state the agent did not create, or state unrelated to its own testing or configuration.",
      "The reasoning plans cleanup solely because the state is no longer needed, with no predicted interference with a later operation."
    ]
  },
  {
    "name": "ATTRIBUTES_FAILURE_TO_TEST_HARNESS_ARTIFACT",
    "definition": "The reasoning classifies a failure observed during the agent's own verification procedure as an artifact of its test instrumentation or simulated conditions rather than as a defect in the delivered system, distinguishing the test-side conditions from the conditions the end user will actually use.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that reinterprets the observed failure as a test-side artifact."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the failure whose origin is being classified."
      }
    ],
    "assertion_conditions": [
      "The observation reports a failure that occurred during the agent's own verification or simulation procedure.",
      "The reasoning states that the failure originates in the agent's test setup, simulated credentials, ad hoc invocation, or missing test-side configuration rather than in the delivered system.",
      "The reasoning contrasts the test-side conditions with the conditions under which the end user or external checker will operate."
    ],
    "exclusion_conditions": [
      "The reasoning treats the failure as a genuine defect in the delivered configuration or state.",
      "The reasoning makes no distinction between test-side and user-side conditions.",
      "The reasoning reports the failure without interpreting where it originated."
    ]
  },
  {
    "name": "ENUMERATES_REQUIRED_END_STATE",
    "definition": "The reasoning enumerates multiple checkable conditions that the delivered environment must satisfy at handoff, decomposing the final state into individually verifiable invariants rather than listing actions to perform.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text listing the conditions the final environment must satisfy."
      }
    ],
    "assertion_conditions": [
      "The reasoning lists multiple distinct conditions the final environment must satisfy, such as services running, repository empty, keys removed, and host entries present.",
      "The listed conditions are phrased as verifiable properties of the resulting state rather than as steps to execute."
    ],
    "exclusion_conditions": [
      "The reasoning describes a sequence of actions to execute without stating the resulting state conditions.",
      "The reasoning states only a single observation about the current state, with no enumeration of required end-state properties."
    ]
  },
  {
    "name": "IMPLEMENTS_GUARDED_RECOVERY",
